--[[
	Midnight Helper — French locale shell (Phase B).
	Load order: after deDE.lua, before nlNL.lua.

	Non-advisor keys inherit from enUS where not overridden.
	GUIDE_ADVISOR_* and per-spec GUIDE_GEAR_* stay English until Phase C.
	Delve tip bodies: DelveTips.lua (deDE/frFR merged at load).
]]

local _, ns = ...

ns._mhLocales = ns._mhLocales or {}

-- Locale-gating (Spec 11 3a): only build this pack when the client is frFR.
-- enUS + nlNL always load, so auto-detect and forced Dutch keep working; forcing
-- frFR on another client shows a login notice and loads once the client is frFR.
if GetLocale() ~= "frFR" then
	return
end

