	DELVELOG_LBL_KEY = "Clé",
	DELVELOG_TOTAL_TIME = "Temps total :",
	INFO_DRAWER_BODY_DELVELOG = "Le Journal des gouffres enregistre chaque gouffre de Midnight que tu termines sur ce personnage. Clique sur un gouffre pour déplier ses dernières runs. Chaque run indique le palier, le temps, les morts, si tu as utilisé une Restored Coffer Key et le boss final. Le suivi tourne en arrière-plan ; cet onglet n'a pas besoin d'être ouvert.",
	TAB_WORLD = "Void & Rituals",
	TAB_EVENTS = "Événements",
	EVENTS_SUBTITLE = "Tous les événements de monde de Midnight : ce qui se passe maintenant et ce qui arrive dans les 24 prochaines heures. Clique sur un événement actif pour tracer un itinéraire ; survole-le pour savoir de quoi il s'agit et ce qu'il rapporte.",
	EVENTS_NONE = "Aucun événement de monde visible pour le moment — le planificateur charge peut-être encore. Réessaie dans quelques secondes.",
