	-- Articles codex du patch 12.0.7
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns : Naigtal & Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "Un portail dans le Voidstorm (Howling Ridge), ou le portail permanent du Bazar de Lune-d'argent, mène vers l'un des deux mondes du Vide qui alternent chaque semaine : Naigtal le fongique ou Val le glacial. Chacun propose des expéditions mondiales, des rares, des événements de zone et un boss mondial (Nexus-Captain Leth'ir / Imperator Pertinax). L'hebdomadaire Showdown octroie une Riftstalker's Cache et compte pour la rangée World de la Grande chambre forte. La Heroic World Tier optionnelle augmente difficulté et récompenses — choix au portail. Départ : Riftblade Maella à Lune-d'argent. En Saison 2, c'est du contenu de rattrapage : bien pour les rerolls et les personnages tout juste niveau 90, pas pour ton meilleur équipement.",
	CODEX_127_SPOREFALL_TITLE = "Raid Sporefall (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Raid à un boss à Harandar : Rotmire, un géant fongique. C'est un raid de la Saison 1 : son équipement (LFR 259 / Normal 272 / Héroïque 285 / Mythique 298) est plus bas que la même difficulté dans le raid de la Saison 2, donc tu y vas pour la monture et l'apparence, pas pour des améliorations. Le Mythique est flexible de 15 à 25 joueurs. Récupère un Delicious Sporesnack une fois par semaine (par compte), peu importe la difficulté — combines-en quatre pour obtenir la monture Luminous Sporeglider.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio & Runes (12.0.7)",
	CODEX_127_FOLIO_BODY = "Nouveau système de puissance sans emplacement d'équipement. Débloqué via la campagne du Sunstrider Omnium avec le magistère Umbric et le grand magistère Rommath à Quel'Danas. Chaque semaine, la quête 'Seeking Knowledge' donne un Mote of Omnial Inquiry pour ouvrir l'une des cinq rangées de runes ; les runes s'échangent librement hors combat.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (30 juin - 11 août)",
	CODEX_127_TIMEWAYS_BODY = "Marathon des Marcheurs du temps avec six donjons Dragonflight. Fais quatre donjons dans la semaine pour le buff Mastery de la semaine ; obtiens Mastery sur quatre semaines distinctes pour la monture Spawn of Vyranoth.",
	CODEX_127_RITUALRENOWN_TITLE = "Renom des Sites rituels (12.0.5)",
	CODEX_127_RITUALRENOWN_BODY = "Les Sites rituels ont une voie de Renom liée au compte (8 rangs) dans la fenêtre Journeys. Monter en rang enrichit chaque site : Regeneration Orbs soignants, puis ennemis rares (rang 4), autels de bonus (rang 5), plus grands trésors (rang 7) et élites rares (rang 8) — tous avec du butin supplémentaire. Cela débloque aussi des articles chez les vendeurs de Lune-d'argent : déco d'habitat du Vide (rang 3, Rae'ana), familiers (rang 6, Sergeant Vornin) et la monture Void-Touched Hawkstrider (rang 8, Sergeant Vornin). Chaque récompense est liée au bataillon (Warband), ta progression compte donc pour tout le compte. Clique sur les Loa Shrines lumineux dans un site pour un buff de stat de 60 minutes (p. ex. +10% de coup critique).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "En cours de développement",
	TAB_BETA_TOOLTIP_BODY = "Cet onglet est en beta précoce — le contenu est incomplet, peut changer souvent et n'est pas prêt pour un usage complet.",
	TAB_ADDONS = "Modules complémentaires",
	SEARCH_CHAT_TAB_ACADEMY = "Onglet ouvert : Académie de rôle",
	ACADEMY_SUBTITLE = "Un court cours sur le tanking, le soin et le DPS en groupe : comment penser, quoi préparer d'abord, et un chemin calme vers les donjons.",
	ACADEMY_TRACK_TANK = "Piste tank",
	ACADEMY_TRACK_HEAL = "Piste soigneur",
	ACADEMY_CLASS_FMT = "Connecté : %s - %s. La carte de ta spé : /mh play",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Macros ouvertes pour %s - %s. Regarde aussi Consommables pour flacons et pots.",
	ACADEMY_PREF_TITLE = "Checklist avant de partir (coche quand tu es prêt)",
	ACADEMY_PREF_HINT = "Les coches sont enregistrées dans tes paramètres. Macros et Consommables sont dans la salle Outils.",
	ACADEMY_PREF_TANK_INTERRUPT = "Mon interruption sur ma barre : la touche elle-même, ou une macro toute prête (onglet Macros)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Une défensive prête (ta carte : /mh play -> Rester en vie)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Flacon / pot prêt (onglet Consommables)",
	ACADEMY_PREF_TANK_TAUNT = "Je connais ma touche de provocation (testée une fois sur un mannequin d'entraînement — il y en a à Lune-d'argent)",
	ACADEMY_PREF_HEAL_MACROS = "Macros de soin mouseover / focus (onglet Macros)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Défensive personnelle sur la barre (ta carte : /mh play -> Rester en vie)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Pot / flacon de mana (onglet Consommables)",
	ACADEMY_PREF_HEAL_PRACTICE = "J'ai soigné un ami une fois en cliquant sur son cadre",
	ACADEMY_TANK_INTRO_TITLE = "Esprit de tank",
	ACADEMY_TANK_INTRO_BODY = "Ton job : faire que les ennemis te frappent toi, pas ton groupe, et donner le rythme — pas faire le plus de dégâts.\n\nUn pull régulier vaut mieux qu'un ordre de touches parfait avec un groupe mort. Dis « pull dans 3 » à voix haute si ça aide.",
	ACADEMY_TANK_PULL_TITLE = "Pendant un pull (10 premières secondes)",
	ACADEMY_TANK_PULL_BODY = "1. Prends le pack : frappe-les tous avec tes attaques qui touchent beaucoup d'ennemis à la fois (AoE). Ne provoque que celui qui part vers quelqu'un d'autre.\n2. Tourne les ennemis pour qu'ils regardent loin du groupe quand tu peux : certains ennemis frappent tout ce qui est devant eux, sinon ton groupe est touché aussi.\n3. Utilise une défensive avant les gros dégâts ou au début d'un gros pull — pas quand ta vie est déjà basse. Une à la fois ; garde une grande pour le plus gros coup.\n4. Interromps le sort qui fait le plus mal (souvent un soin ou un gros coup).\n\nTu n'as pas besoin d'appuyer sur toutes tes touches en même temps.",
	ACADEMY_TANK_WIPE_TITLE = "Quand ça tourne mal",
	ACADEMY_TANK_WIPE_BODY = "Un wipe, c'est des données, pas un verdict. Demande-toi : « Trop en avance ? » ou « J'ai appuyé sur une défensive avant le gros coup ? »\n\nReprends ton souffle, mange et bois, réessaie.",
	ACADEMY_TANK_DUNGEON_TITLE = "Ton premier donjon normal (après un donjon avec sujets)",
	ACADEMY_TANK_DUNGEON_BODY = "Va avec des amis ou ta guilde si possible ; sinon, un groupe aléatoire, c'est très bien. Invite d'abord tes amis : clic droit sur leur nom dans le chat -> Inviter, ou tape /inv et leur nom. Ensuite, le chef du groupe appuie sur « Trouver un groupe ».\n\nAvant « Trouver un groupe », coche l'icône Tank (soigneurs : l'icône Soigneur). Sans rôle coché, le bouton ne marche pas. Tu n'es pas le chef ? Quand le chef appuie sur « Trouver un groupe », tu reçois « Confirmez votre rôle : » : coche ton rôle et clique sur « Accepter ».\n\nPull doucement — deux petits packs valent mieux qu'un énorme pull de plusieurs packs à la fois.\n\nSurveille le mana du soigneur ; pause entre les pulls. Demander un CC ou « pas de gros pull pour l'instant », c'est ok.",
	ACADEMY_TANK_RAID_TITLE = "Raids et LFR (plus tard)",
	ACADEMY_TANK_RAID_BODY = "LFR est l'intro raid douce : indulgent, beaucoup de soigneurs. Fais attention aux grosses attaques du boss et reste au bon endroit.\n\nLe tank en raid mythique n'est pas l'étape suivante — d'abord le confort en héroïque/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "Chat de groupe",
	ACADEMY_CHAT_HINT = "Clique une ligne (ou son icône copier) et appuie sur Ctrl+C. Appuie sur Entrée : le chat s'ouvre sur Dire, que seuls les gens près de toi voient. Pour ton groupe, tape d'abord /p et un espace ; dans un donjon de la Recherche de groupe, tape /i. Puis Ctrl+V pour coller et Entrée pour envoyer. Mets le nom du sort de l'ennemi à la place de [nom du sort].",
	ACADEMY_CHAT_COPY_TIP = "Sélectionne cette ligne (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Tank en apprentissage — allez doucement svp.\"\n\"Pull dans 3...\"\n\"Pause mana.\"\n\"Inter sur [nom du sort] — je le prends après.\"\n\"Encore un essai — je connais ce pull.\"",
	ACADEMY_TANK_LADDER_TITLE = "Échelle d'anxiété (ordre conseillé)",
	ACADEMY_TANK_LADDER_BODY = "1. Élites (des ennemis plus forts) dehors dans le monde, avec un ami\n2. Gouffres (petite instance — onglet Gouffres)\n3. Donjon avec sujets : des PNJ complètent le groupe (niveau 80-90). Recherche de groupe -> Donjons -> Donjons avec sujets\n4. Donjon normal avec des gens de confiance\n5. Héroïque / LFR quand tu es à l'aise\n\nReste sur une étape jusqu'à ce qu'elle devienne ennuyeuse au lieu d'effrayante. Passe ensuite à la suivante.",
	ACADEMY_TANK_BOTH_TITLE = "Tu apprends aussi à soigner ?",
	ACADEMY_TANK_BOTH_BODY = "La piste DPS est le second rôle le plus doux — tes touches, tes interruptions et ton placement, sans groupe qui dépend de toi. Soigner, c'est le plus grand saut, mais tu sais déjà lire les pulls, et c'est la moitié du travail.\n\nChoisis un rôle principal en donjon pendant un moment et entraîne l'autre en gouffres ou dehors dans le monde. Changer de rôle dans le même M+ avec des inconnus double le stress ; maîtriser un rôle d'abord donne confiance pour le second.",
	ACADEMY_HEAL_INTRO_TITLE = "État d'esprit soigneur",
	ACADEMY_HEAL_INTRO_BODY = "Tu n'es pas responsable de tout le monde à 100 % PV tout le temps.\n\nTon job : triage — garder le tank en vie, sauver celui qui va mourir, puis le reste. Un peu de dégâts est normal — l'overheal paniqué vide le mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (qui en premier ?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Toi (si tu meurs — un soigneur mort ne soigne personne)\n2. Tank (si le pack est encore sur lui)\n3. Quiconque sous ~40 % ou avec un debuff mortel\n4. Le reste avec des soins efficaces\n\nQuelqu'un va mourir : d'abord un soin qui arrive tout de suite (marqué [Instantané] dans ta boîte à outils de soin — son infobulle dit aussi « Instantané »). Aucun n'est prêt ? Ton soin [Incantation courte]. Beaucoup de dégâts et le temps d'incanter : ton gros soin (druide : ton soin direct avec incantation). Calme : un soin qui coûte peu de mana (l'infobulle montre le coût).",
	ACADEMY_HEAL_WIPE_TITLE = "Quand ça tourne mal",
	ACADEMY_HEAL_WIPE_BODY = "« Aurais-je pu sauver le tank ? » est la bonne question — pas « pourquoi le DPS est resté dans ce qui fait mal ? »\n\nSi le mana était vide, utilise des sorts plus efficaces la prochaine fois. Un wipe ne veut pas dire que tu ne peux pas soigner.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Ton premier donjon normal (après un donjon avec sujets)",
	ACADEMY_HEAL_DUNGEON_BODY = "Avec des amis si possible, sinon un groupe aléatoire (les étapes plus haut montrent comment). Coche l'icône Soigneur avant d'appuyer sur « Trouver un groupe ».\n\nDis au groupe que tu apprends. Reste assez près du tank pour que tes soins l'atteignent (à portée) ; laisse le DPS prendre une égratignure avant de brûler le mana.\n\nEntre les pulls : boire, buff, respirer. « OOM, 5 sec », c'est ok.",
	ACADEMY_HEAL_RAID_TITLE = "Raids et LFR (plus tard)",
	ACADEMY_HEAL_RAID_BODY = "LFR : les dégâts sur tout le raid sont prévisibles après un seul wipe. Apprends quand arrivent les gros coups du boss (la frise Techniques des boss les montre), pas les barres de chaque joueur.\n\nLes soins en raid suivent le même triage : d'abord les fenêtres de cooldowns du tank et du raid.",
	ACADEMY_HEAL_CHAT_TITLE = "Chat de groupe",
	ACADEMY_HEAL_CHAT_BODY = "\"Soigneur en apprentissage - je préviens quand je suis bas en mana.\"\n\"Le tank est prioritaire - criez si vous avez besoin d'une pause.\"\n\"Gros soin sur toi - surveille ta santé.\"\n\"OOM - 5 secondes de pause entre les pulls.\"\n\"C'était de ma faute - j'en garderai plus pour le tank au prochain pull.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Échelle d'anxiété (ordre recommandé)",
	ACADEMY_HEAL_LADDER_BODY = "1. Soigne un ami dehors dans le monde (pas en donjon)\n2. Gouffres en petit groupe\n3. Donjon avec sujets : des PNJ complètent le groupe (niveau 80-90). Recherche de groupe -> Donjons -> Donjons avec sujets\n4. Donjon normal avec des amis patients\n5. Raid LFR / héroïque quand tu es prêt\n\nLes gouffres sont l'étape la plus douce vers le contenu instancié.",
	ACADEMY_HEAL_BOTH_TITLE = "Tu apprends aussi le tank ?",
	ACADEMY_HEAL_BOTH_BODY = "La piste DPS est le second rôle le plus doux — juste tes touches, tes interruptions et ton placement, sans pression sur le groupe. En tank, tu attends le moins longtemps pour un groupe de donjon, une fois que tanker te fait moins peur.\n\nDeux rôles en une semaine avec des inconnus, c'est beaucoup — un rôle « principal » réduit la peur.",
	INFO_DRAWER_BODY_ACADEMY = "Académie de rôle : pistes tank, soigneur et DPS, checklist avant de partir, notes donjon et raid, et lignes pour le chat de groupe. Ouvre-la à tout moment avec /mh academy (ou /mh academy tank, /mh academy heal). Macros et Consommables sont dans la salle Outils.",
