	INFO_DRAWER_BODY_CONSUMABLES = "Consommables Midnight par spécialisation (liste Wowhead). Utilise Mon personnage, < > ou la recherche (par exemple Havoc, Beast) pour prévisualiser une autre spécialisation sans te reconnecter.",
	MACROS_MACRO_NAME_FMT = "%s",
