	KEYBIND_ROLE_COOLDOWN = "Barre de temps de recharge",
	LAYOUT_PROTOTYPE_SUBTITLE = "Aperçu complet du clavier : les touches Midnight s'allument, les autres sont grisées. Survole une touche pour voir tous ses raccourcis — un badge +N signifie N raccourcis Shift/Ctrl en plus. Les astuces de l'onglet Guide peuvent renvoyer ici et mettre une touche en surbrillance.",
	LAYOUT_KEY_UNUSED_TOOLTIP = "|cff888888Non utilisée dans la carte de raccourcis Midnight de cette spécialisation.|r",
	LAYOUT_KEY_MODIFIER_TOOLTIP = "|cff888888Touche de modification — WoW gère les combos Shift/Ctrl/Alt séparément de cette carte de sorts.|r",
	LAYOUT_KEY_NAV_TOOLTIP = "|cff888888Cluster de navigation/édition — ne fait pas partie de la carte des touches Midnight.|r",
	LAYOUT_KEY_EMPTY_TOOLTIP = "|cffaaaaaaPas encore de rôle sur cette touche dans la carte de la spécialisation actuelle.|r",
	LAYOUT_KEY_G_OPTIONAL_TOOLTIP = "|cffaaaaaaL'emplacement G existe dans la grille, mais cette équipe le laisse souvent vide — raccourci facultatif.|r",
	LAYOUT_KEY_ROLE_TOOLTIP_FMT = "|cffffcc00%s|r",
	LAYOUT_KEY_BIND_LAYER_FMT = "|cffe0e070%s|r — %s",
	LAYOUT_KEY_MOVEMENT_TOOLTIP = "Déplace ton personnage : W pour avancer, S pour reculer, A/D pour te décaler sur le côté, la souris pour tourner. WoW les utilise par défaut – garde-les libres pour te déplacer.",
	LAYOUT_KEY_TAB_TOOLTIP = "Tab change de cible. WoW l'utilise par défaut – garde Tab libre pour pouvoir choisir rapidement le bon ennemi au combat.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Astuce Midnight : garde cette touche libre pour les sorts, les macros ou les combos Shift/Ctrl/Alt — même idée que les touches F allumées sur tes barres d'action.",
	LAYOUT_LEGEND = "|cff33ff61Vert|r = déplacement (W A S D).\n|cffe0e070Or|r = sorts et raccourcis sur cette carte.\n|cff59d9ffTab|r = changer de cible rapidement.\n|cff888888Gris|r = pas sur cette carte de départ.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Ouvert depuis ton guide de leveling — cette touche est sur la carte Midnight.|r",
	MODULE_PLACEHOLDER = "Espace réservé au module — le contenu de \"%s\" sera monté ici.",
	INFO_DRAWER_TOGGLE_SHOW = "Informations",
	INFO_DRAWER_TOGGLE_HIDE = "Fermer",
	INFO_DRAWER_TITLE_FMT = "%s - Comment utiliser",
	INFO_DRAWER_BODY_DELVES = "Centre gouffres Midnight pour ton personnage actuel.\n\nDéplie Grande chambre forte pour le suivi hebdo des récompenses, ou Gouffres Midnight pour les monnaies de saison (Restored Coffer Keys, éclats hebdo, Undercoins), Périple du gouffre / renommée et la liste des gouffres avec détection des gouffres abondants via les POI carte.\n\nNavigation : clic droit sur une ligne pour un itinéraire vers l'entrée. |cffffcc00TomTom (recommandé)|r ajoute la flèche carte et la file de waypoints. |cff00ff00Travel Assistant|r (popup si tu es loin) propose les raccourcis pierre de foyer et portail du hub et fonctionne |cffffff00sans|r TomTom.\n\nTrouver le gouffre abondant le plus proche nécessite TomTom.",
	INFO_DRAWER_BODY_ACCOUNT = "Liste de tes personnages stockée localement par cet addon (variables enregistrées sur ton PC, pas de synchronisation cloud Blizzard).\n\nChaque ligne montre les clés, les éclats, les Undercoins, un rappel de tes métiers et un résumé compact de la Grande chambre forte avec des info-bulles détaillées ; ton personnage connecté est mis en surbrillance et le tri place les plus utiles en premier.\n\nLes lignes se mettent à jour à la connexion et lors des changements de monnaie ou des événements hebdo. Supprimer n'efface que l'instantané enregistré par l'addon, jamais ton vrai personnage WoW.",
	INFO_DRAWER_BODY_RARES = "Rares du monde Midnight par zone (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nChoisis une zone à gauche. Vert = fait cette semaine sur CE personnage (un reroll peut encore le looter) ; UP vert = vignette au spawn (probablement actif) ; tiret gris = pas sur ta carte pour l'instant.\n\nRare le plus proche = un pin ; Générer la route = tous les rares ouverts dans TomTom. Le statut UP est indicatif — ouvre la carte de zone ou rapproche-toi si doute.",
	RARES_TITLE = "Rares Midnight",
	RARES_SUBTITLE_FMT = "%d/%d faits cette semaine sur ce personnage · %d visibles sur la carte (étoile argentée)",
	RARES_EMPTY_ZONE = "Aucune liste de rares pour cette zone.",
	RARES_BTN_NEAREST = "Rare le plus proche",
	RARES_BTN_ROUTE = "Générer la route",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper :|r TomTom : rare le plus proche — %s",
	RARES_NEAREST_NONE = "Plus aucun rare incomplet dans cette zone.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant indisponible (module Gouffres non chargé).",
	RARES_ROUTE_DONE_FMT = "%d/%d rares incomplets ajoutés à TomTom. %s",
	RARES_ROUTE_ORDER_NEAR = "Ordre : le plus proche d'abord, puis le suivant à chaque étape.",
	RARES_ROUTE_ORDER_LIST = "Ordre : ordre de la liste (position indisponible).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Fait sur ce personnage — il rouvre au prochain reset. Un autre de tes personnages peut encore le looter.",
	RARES_TIP_UP = "Probablement actif (vignette carte au spawn).",
	RARES_TIP_DOWN = "Pas sur la carte pour l'instant — peut spawn plus tard.",
	RARES_TIP_VIGNETTE_NOTE = "Statut carte indicatif ; ouvre la carte de zone ou rapproche-toi si incertain.",
	INFO_DRAWER_BODY_SMC = "Référence de Silvermoon City pour Midnight (carte 2393). La même liste commence par la checklist hebdo / hub quand les ID de quête sont renseignés, puis continue avec des grilles d'épingles par catégorie — services essentiels, voyage, hubs de quêtes, formateurs de métiers, récolte, et plus encore.\n\nChaque bouton de lieu pose le point de passage Blizzard et, si TomTom est installé, le reproduit via la commande slash (/way #2393 …).\n\nLa progression de la checklist colore en vert les boutons de point de passage liés ; mets à jour les ID de quête dans les données après les gros patchs si une ligne semble fausse.",
	INFO_DRAWER_BODY_PROFESSIONS = "Suit les points de connaissance (KP) de tes métiers de Midnight sur ton personnage actuel, ainsi que les lignes de monnaie quand le client les fournit (Abondance sans alliage, Aplomb artisanal, Éclats de Dundun hebdomadaires).\n\nEn dessous, deux colonnes répertorient les quêtes de connaissance et les livres de chaque métier : des icônes indiquent si chaque quête est terminée. Clique sur une ligne pour envoyer uniquement ce repère à TomTom (efface les autres waypoints ; Travel Assistant gère les sauts entre zones lorsque TomTom est chargé).\n\nLes boutons du bas mettent en file d'attente les repères incomplets : générer des trésors ou générer des livres (le plus proche d'abord quand ta position sur la carte est disponible).",
	INFO_DRAWER_BODY_GUIDE = "Références de leveling spécialisation par spécialisation, dans le style d'Icy Veins : priorité des statistiques, choix d'équipement, consommables filtrés en fonction de ce que ton niveau peut réellement utiliser, lignes d'astuces de sorts facultatives et le conseiller de leveling avec des onglets par tranche de niveau pour la rotation, les défensifs et les priorités de talents.\n\nQuand ta classe a une carte de touches Midnight (Chasseur / Paladin pour l'instant), les astuces peuvent afficher un bouton de touche doré - clique dessus pour ouvrir l'onglet Disposition et mettre en surbrillance cette touche sur le clavier. Cela relie la lecture (sur quoi appuyer) au placement (où sur le clavier), tu apprends donc en pratiquant.\n\nLa barre de recherche globale comprend les mots-clés du guide et peut passer d'un onglet de Midnight Helper à l'autre ; l'aperçu te permet de lire une autre spécialisation sans te reconnecter, et Mon personnage revient à ta spécialisation active.\n\nLa visibilité de l'onglet Guide suit les paramètres : Auto (masqué au niveau 90+), Toujours afficher ou Toujours masquer.",
	INFO_DRAWER_BODY_MACROS = "Onglet Interrompre : la macro d'interruption de l'équipe (focus d'abord). Onglet Utilitaire : macros supplémentaires pour ta spécialisation (sorts au sol au curseur, soins en mouseover, etc.) tirées du pack de l'équipe. Choisis une ligne, lis l'astuce, copie le texte.\n\nLes données peuvent changer après les correctifs - signale les sorts manquants à l'équipe.",
	INFO_DRAWER_BODY_ADDONS = "Hub pour les outils facultatifs regroupés dans Midnight Helper plutôt que des téléchargements séparés.\n\nChoisis un sous-onglet en haut. Il s'agit aujourd'hui de Platynator : lien Wago, importation de chaîne de profil et galerie visuelle MF Platynator.\n\nDes panneaux de partenaires supplémentaires s'enregistrent automatiquement ici lors de la livraison des futurs modules.",
	ABOUT_WINDOW_TITLE = "À propos de Midnight Helper",
	ABOUT_VERSION_FMT = "Version installée : |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Auteurs : TwelveInchy & Claude\n\nTon compagnon Midnight tout-en-un, organisé en quatre salles — Me, Codex, Tools et Settings. Épingle tes favoris sous la barre de recherche et tape pour aller partout. Avec Cette semaine, Gouffres & Chambre forte, coachs Gouffre & Rituel, le conseiller Enchantements & Gemmes, aperçu du compte, guides Codex, professions et outils intégrés — EN / NL / DE / FR / ES / PT / IT.\n\nMerci aux addons et guides avec lesquels nous avons vérifié nos informations : DBM (capacités des boss et ID de sorts), HandyNotes_Midnight (emplacements des rares et des trésors), GTFO (ID de sorts des dangers), RareScanner (gestion des vignettes), ainsi que Wowhead, Icy Veins, Method et wowcarry. Nous prenons les ID et les chiffres comme des pistes et les vérifions dans le jeu lui-même dès que possible ; aucun code de ces addons n'est utilisé.",
